mapper.select:
SELECT s.*, c.name clazzName, (case when s.degree = 1 then '初中' when s.degree = 2 then '高中' when s.degree = 3 then '大专' when s.degree = 4 then '本科' when s.degree = 5 then '硕士' when s.degree = 6 then '博士' end) FROM student s LEFT JOIN clazz c on s.clazz_id = c.id
s.name LIKE concat('%',#{name},'%')
AND s.degree = #{degree}
AND s.clazz_id = #{clazzId}
ORDER BY s.update_time desc

